import InvariantSwiftCore
import InvariantSwift
import Testing

/// Integration tests that verify the actual execution of property tests
/// generated by the @PropertyTest macro expansion pattern.
///
/// These tests validate:
/// 1. Property creation and configuration works correctly
/// 2. Generator inference produces valid generators
/// 3. PropertyRunner executes and returns correct results
/// 4. Result handling (success, failure, gaveUp) works as expected
struct PropertyMacroIntegrationTests {

  // MARK: - Basic Property Execution Tests

  @Test("Property test with Int parameter succeeds for valid property")
  func propertyTestIntSucceeds() throws {
    // This simulates the expansion of:
    // @PropertyTest func testInt(x: Int) { #expect(x == x) }

    let generator = Gen<Int>.int
    let property = Property(generator: generator) { (x: Int) in
      // swiftlint:disable:next identical_operands
      x == x  // Always true - identity property (testing reflexivity)
    }

    let config = PropertyConfig(iterations: 100, maxShrinks: 100)
    let result = runPropertySynchronously(property, config: config)

    switch result {
    case .success:
      break  // Expected
    case .failure:
      Issue.record("Property should have succeeded")

    case .gaveUp:
      Issue.record("Property should not have given up")
    }
  }

  @Test("Property test with String parameter succeeds for valid property")
  func propertyTestStringSucceeds() throws {
    let generator = Gen<String>.string
    let property = Property(generator: generator) { (_: String) in
      true  // String identity: always passes
    }

    let config = PropertyConfig(iterations: 100, maxShrinks: 100)
    let result = runPropertySynchronously(property, config: config)

    switch result {
    case .success:
      break  // Expected
    case .failure:
      Issue.record("Property should have succeeded")

    case .gaveUp:
      Issue.record("Property should not have given up")
    }
  }

  @Test("Property test with Bool parameter succeeds for valid property")
  func propertyTestBoolSucceeds() throws {
    let generator = Gen<Bool>.bool
    let property = Property(generator: generator) { (value: Bool) in
      // swiftlint:disable:next identical_operands
      value == value  // Identity (testing reflexivity)
    }

    let config = PropertyConfig(iterations: 100, maxShrinks: 100)
    let result = runPropertySynchronously(property, config: config)

    switch result {
    case .success:
      break

    case .failure:
      Issue.record("Property should have succeeded")

    case .gaveUp:
      Issue.record("Property should not have given up")
    }
  }

  // MARK: - Multiple Parameter Tests (Gen.zip pattern)

  @Test("Property test with two Int parameters using Gen.zip")
  func propertyTestTwoIntsWithZip() throws {
    // Simulates expansion with multiple parameters:
    // @PropertyTest func test(a: Int, b: Int) { #expect((a + b) - a == b) }

    let generator = Gen<Int>.int.zip(Gen<Int>.int)
    let property = Property(generator: generator) { (tuple: (Int, Int)) in
      let (lhs, rhs) = tuple
      // Addition commutativity (works for all Int, avoiding overflow)
      return lhs &+ rhs == rhs &+ lhs
    }

    let config = PropertyConfig(iterations: 100, maxShrinks: 100)
    let result = runPropertySynchronously(property, config: config)

    switch result {
    case .success:
      break

    case .failure:
      Issue.record("Property should have succeeded")

    case .gaveUp:
      Issue.record("Property should not have given up")
    }
  }

  @Test("Property test with three parameters using Gen.zip3")
  func propertyTestThreeParamsWithZip() throws {
    // swiftlint:disable:next large_tuple
    let generator = Gen<(Int, String, Bool)>.zip3(
      Gen<Int>.int,
      Gen<String>.string,
      Gen<Bool>.bool
    )
    // swiftlint:disable:next large_tuple
    let property = Property(generator: generator) { (_: (Int, String, Bool)) in
      true  // Property always succeeds - testing Gen.zip3 integration
    }

    let config = PropertyConfig(iterations: 50, maxShrinks: 50)
    let result = runPropertySynchronously(property, config: config)

    switch result {
    case .success:
      break

    case .failure:
      Issue.record("Property should have succeeded")

    case .gaveUp:
      Issue.record("Property should not have given up")
    }
  }

  // MARK: - Collection Type Generator Tests

  @Test("Property test with Array<Int> parameter")
  func propertyTestArrayInt() throws {
